export interface SupplyLotInput {
  code: string;
  description: string;
  quantity: number;
  labels: readonly string[];
}

export interface SupplyLotDetails {
  code: string;
  description: string;
  quantity: number;
  labels: string[];
}

export class SupplyLot {
  private readonly data: SupplyLotDetails;

  constructor(input: SupplyLotInput) {
    this.data = { ...input, labels: [...input.labels] };
  }

  validate(): string[] {
    const issues: string[] = [];
    if (this.data.code.length === 0) issues.push("code");
    if (!this.data.description.trim()) issues.push("description");
    if (!Number.isInteger(this.data.quantity) || this.data.quantity <= 0) issues.push("quantity");
    if (this.data.labels.some(label => !label.trim())) issues.push("labels");
    return issues;
  }

  details(): SupplyLotDetails {
    return { ...this.data, labels: [...this.data.labels] };
  }
}
```

