import { SupplyLot } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const input = { code: 'L1', description: 'Lot one', quantity: 3, labels: ['cold', 'fragile'] };
const lot = new SupplyLot(input);
input.code = 'changed';
input.description = 'changed';
input.quantity = 99;
input.labels[0] = 'changed';
const first = lot.details();
equal(first.code, 'L1', 'code defensively copied');
equal(first.description, 'Lot one', 'description defensively copied');
equal(first.quantity, 3, 'quantity defensively copied');
equal(first.labels.join(','), 'cold,fragile', 'labels defensively copied');
equal(lot.validate().length, 0, 'valid lot');

const second = lot.details();
assert(second !== first, 'details returns new object');
assert(second.labels !== first.labels, 'details returns new labels array');
first.code = 'mutated result';
first.labels.push('mutated result');
equal(lot.details().code, 'L1', 'details object cannot mutate storage');
equal(lot.details().labels.length, 2, 'details labels cannot mutate storage');

const invalid = new SupplyLot({ code: ' \t ', description: '\n', quantity: 2.5, labels: ['ok', '  '] });
equal(invalid.validate().join(','), 'code,description,quantity,labels', 'issues use exact order');
equal(new SupplyLot({ code: '', description: 'ok', quantity: 0, labels: [] }).validate().join(','), 'code,quantity', 'empty labels allowed');
equal(new SupplyLot({ code: 'ok', description: 'ok', quantity: -1, labels: ['x'] }).validate().join(','), 'quantity', 'negative quantity invalid');
equal(new SupplyLot({ code: 'ok', description: 'ok', quantity: Infinity, labels: ['x'] }).validate().join(','), 'quantity', 'nonfinite quantity invalid');

const labels = ['good', '   '];
const validationLot = new SupplyLot({ code: 'ok', description: 'ok', quantity: 1, labels });
const issues = validationLot.validate();
equal(issues.join(','), 'labels', 'blank label detected');
equal(labels.join(','), 'good,   ', 'validation does not mutate caller labels');

